<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/system/app/bootstrap.php'; require dirname(__DIR__,2).'/system/ui/layout.php';
$user=enterprise_require_auth('../../'); enterprise_require_capability($user,'permissions.manage'); $pdo=enterprise_pdo(); enterprise_upgrade($pdo); enterprise_sync_module_capabilities($pdo,dirname(__DIR__,2).'/modules');
if($_SERVER['REQUEST_METHOD']==='POST'){enterprise_check_csrf((string)($_POST['csrf']??''));$rid=(int)($_POST['role_id']??0);$roleCheck=$pdo->prepare('SELECT name FROM roles WHERE id=? LIMIT 1');$roleCheck->execute([$rid]);$roleName=(string)($roleCheck->fetchColumn()?:'');if(in_array($roleName,['admin','superadmin'],true))throw new RuntimeException('Die Capabilities der geschützten Systemrollen admin und superadmin werden zentral verwaltet.');$caps=array_keys((array)($_POST['caps']??[]));$pdo->prepare('DELETE FROM role_capabilities WHERE role_id=?')->execute([$rid]);$q=$pdo->prepare('SELECT id FROM capabilities WHERE name=?');$i=$pdo->prepare('INSERT IGNORE INTO role_capabilities(role_id,capability_id) VALUES (?,?)');foreach($caps as $c){$q->execute([$c]);if($id=$q->fetchColumn())$i->execute([$rid,$id]);}enterprise_audit($pdo,(int)$user['id'],'permissions.update','role',(string)$rid,['capabilities'=>$caps]);}
$roles=$pdo->query('SELECT * FROM roles ORDER BY name')->fetchAll();$caps=$pdo->query('SELECT * FROM capabilities ORDER BY module_name,name')->fetchAll();$assigned=[];foreach($pdo->query('SELECT role_id,c.name FROM role_capabilities rc JOIN capabilities c ON c.id=rc.capability_id')->fetchAll() as $r)$assigned[(int)$r['role_id']][]=$r['name'];
ob_start();render_breadcrumbs([['label'=>'Enterprise','href'=>'../dashboard.php'],['label'=>'Berechtigungen','href'=>'']]);?><section class="hero"><span class="badge">RC1.7 · Phase L</span><h1>Capabilities & Rollen</h1><p>Feingranulare Rechte für Core und Module.</p></section><?php foreach($roles as $role):$protected=in_array((string)$role['name'],['admin','superadmin'],true);?><section class="card"><h2><?=e($role['label'])?></h2><?php if($protected):?><p>Geschützte Systemrolle: alle Capabilities werden zentral und vollständig zugewiesen.</p><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(enterprise_csrf())?>"><input type="hidden" name="role_id" value="<?=$role['id']?>"><?php foreach($caps as $c):?><label style="display:block;margin:.4rem 0"><input type="checkbox" name="caps[<?=e($c['name'])?>]" <?=($protected||in_array($c['name'],$assigned[(int)$role['id']]??[],true))?'checked':''?> <?=$protected?'disabled':''?>> <code><?=e($c['name'])?></code> — <?=e($c['label'])?><?=!empty($c['module_name'])?' ['.e($c['module_name']).']':''?></label><?php endforeach;?><?php if(!$protected):?><button class="button" type="submit">Speichern</button><?php endif;?></form></section><?php endforeach;?><?php $content=ob_get_clean();render_page(['title'=>'Capabilities & Rollen','active'=>'security','base'=>'../../','content'=>$content,'app_nav'=>true,'user'=>$user]);
